fn mall_equal1(v: &[i32]) -> bool {
    // An empty array or a single-element array is considered to have all identical elements
    if v.len() <= 1 {
        return true;
    }

    // Get the first element to compare against
    let first = v[0];

    // Iterate through the array starting from the second element
    for &item in &v[1..] {
        if item != first {
            return false; // Found a different element
        }
    }

    true // All elements are identical
}